import{_ as e,o,c as a,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const n=JSON.parse('{"title":"1962年 · 邓普斯特的价值盘活","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1962年.md","filePath":"05_quotes/by-year/1962年.md"}'),l={name:"05_quotes/by-year/1962年.md"};function u(q,t,s,h,c,_){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1962年-·-邓普斯特的价值盘活" tabindex="-1">1962年 · 邓普斯特的价值盘活 <a class="header-anchor" href="#_1962年-·-邓普斯特的价值盘活" aria-label="Permalink to &quot;1962年 · 邓普斯特的价值盘活&quot;">​</a></h1><blockquote><p>&quot;永远不要指望靠卖得好赚钱。要让买入价格足够便宜，哪怕卖得平平无奇，也能赚到不错的收益。如果能卖个好价钱，那只是锦上添花。&quot;——巴菲特（32岁）</p></blockquote><p>本页收录1962年致股东信中的经典语录。这一年，巴菲特详细讲述了邓普斯特农机制造公司的资产盘活故事，通过换帅哈里·博特尔，将资不抵债的制造企业重塑为净现金充裕的投资平台。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;永远不要指望靠卖得好赚钱。要让买入价格足够便宜，哪怕卖得平平无奇，也能赚到不错的收益。如果能卖个好价钱，那只是锦上添花。&quot;</p></blockquote><blockquote><p>&quot;道指下跌25%、我们下跌15%的年份，远比我们和道指都上涨20%的年份要成功得多。&quot;</p></blockquote><blockquote><p>&quot;真正的保守主义，只能源于知识与理性。&quot;</p></blockquote><blockquote><p>&quot;我认为，检验我们投资方式保守程度最客观的标准，就是看我们在下跌市场中的业绩表现，尤其是道指大幅下跌的环境。&quot;</p></blockquote><blockquote><p>&quot;无论我们的投资组合与道指有多少相似，在任何一年里，我们都注定会有年份大幅跑输道指。&quot;</p></blockquote><blockquote><p>&quot;我认为，长期来看，每年跑赢道指10个百分点，已经是投资所能达到的极限水平。&quot;</p></blockquote><blockquote><p>&quot;我认为，道指通过股息和股价上涨，大概率能实现年化5%-7%的复利收益。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1962年是经典熊市年，道指大跌7.6%，而合伙企业取得13.9%的正收益，超额收益超过22个百分点。巴菲特通过邓普斯特案例完美展示了&quot;资产盘活&quot;模式：买入低价资产→更换管理层→盘活资产→出售。登普斯特股价从16美元涨至每股含51美元现金+证券，账面净资产大幅提升。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1962年-翻译-·-01-letters-1962年-核心总结-·-01-letters-1962年-思维导图" tabindex="-1"><a href="/01_letters/1962年/翻译.html">01_letters/1962年/翻译</a> · <a href="/01_letters/1962年/核心总结.html">01_letters/1962年/核心总结</a> · <a href="/01_letters/1962年/思维导图.html">01_letters/1962年/思维导图</a> <a class="header-anchor" href="#_01-letters-1962年-翻译-·-01-letters-1962年-核心总结-·-01-letters-1962年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1962年/翻译]] · [[→ 核心总结|01_letters/1962年/核心总结]] · [[→ 思维导图|01_letters/1962年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1962年/翻译.html">/01_letters/1962年/翻译</a></li></ul>',20)])])}const b=e(l,[["render",u]]);export{n as __pageData,b as default};
